    LocalizedName('Punarbas', 'Punarbas'),
    District.kanchanpur,
    LocalLevelType.municipality,
  ),

  /// Shuklaphanta Municipality, Kanchanpur District. Nepali name pending.
  shuklaphanta(
    'L70909',
    LocalizedName('Shuklaphanta', 'Shuklaphanta'),
    District.kanchanpur,
    LocalLevelType.municipality,
  );

  const LocalLevel(this.code, this.name, this.district, this.type);

  @override
  final String code;

  @override
  final LocalizedName name;

  /// The district this local level belongs to.
  final District district;

  /// Metropolitan city, municipality, etc.
  final LocalLevelType type;

  @override
  AdminLevel get level => AdminLevel.localLevel;
}

/// Protected areas that lie outside every local level.
///
/// This is not a complete list of protected areas in Nepal: parks such as
/// Sagarmatha lie inside local levels and are not listed here.
enum ProtectedArea {
  /// Bardiya National Park.
  bardiya(
    'PA01',
    LocalizedName('Bardiya', 'बर्दिया'),
    ProtectedAreaType.nationalPark,
    [District.bardiya],
  ),

  /// Chitwan National Park.
  chitwan(
    'PA02',
    LocalizedName('Chitwan', 'चितवन'),
    ProtectedAreaType.nationalPark,
    [
      District.parsa,
      District.chitwan,
      District.makwanpur,
      District.nawalparasiEast,
    ],
  ),

  /// Dhorpatan Hunting Reserve.
  dhorpatan(
    'PA03',
    LocalizedName('Dhorpatan', 'ढोरपाटन'),
    ProtectedAreaType.huntingReserve,
    [District.baglung, District.myagdi, District.rukumEast],
  ),

  /// Khaptad National Park.
  khaptad(
    'PA04',
    LocalizedName('Khaptad', 'खप्तड'),
    ProtectedAreaType.nationalPark,
    [District.achham, District.bajhang, District.bajura, District.doti],
  ),

  /// Koshi Tappu Wildlife Reserve.
  koshiTappu(
    'PA05',
    LocalizedName('Koshi Tappu', 'कोशी टप्पु'),
    ProtectedAreaType.wildlifeReserve,
    [District.sunsari, District.udayapur, District.saptari],
  ),

  /// Langtang National Park.
  langtang(
    'PA06',
    LocalizedName('Langtang', 'लाङटाङ'),
    ProtectedAreaType.nationalPark,
    [District.nuwakot],
  ),

  /// Lumbini Sanskritik Development Area.
  lumbiniSanskritik(
    'PA07',
    LocalizedName('Lumbini Sanskritik', 'लुम्बिनी सांस्कृतिक'),
    ProtectedAreaType.developmentArea,
    [District.rupandehi],
  ),

  /// Parsa Wildlife Reserve.
  parsa(
    'PA08',
    LocalizedName('Parsa', 'पर्सा'),
    ProtectedAreaType.wildlifeReserve,
    [District.bara, District.parsa, District.makwanpur],
  ),

  /// Shivapuri Watershed and Wildlife Reserve.
  shivapuri(
    'PA09',
    LocalizedName('Shivapuri', 'शिवपुरी'),
    ProtectedAreaType.watershedAndWildlifeReserve,
    [District.nuwakot],
  ),

  /// Shuklaphanta National Park.
  shuklaphanta(
    'PA10',
    LocalizedName('Shuklaphanta', 'शुक्लाफाँटा'),
    ProtectedAreaType.nationalPark,
    [District.kanchanpur],
  );

  const ProtectedArea(this.code, this.name, this.type, this.districts);

  /// Stable code, e.g. `PA01`.
  final String code;

  /// Name without the type, e.g. "Chitwan".
  final LocalizedName name;

  /// National park, wildlife reserve, etc.
  final ProtectedAreaType type;

  /// Districts the area extends into.
  final List<District> districts;
}

